const RUNTIME_LABEL: Record<string, string> = {
  vllm: "VLLM",
  omlx: "OMLX",
  llamacpp: "LLAMA.CPP",
  llamaswap: "LLAMA-SWAP",
  openai: "OPENAI",
};

function ContextBar({ used, total }: { used: number; total: number | null }) {
  // No context window configured — show just the count, no bar.
  if (total == null) {
    return (
      <span className="hint ctx-bar-inline" title={`~${used} tokens (context window unknown)`}>
        {fmtTokens(used)} tok
      </span>
    );
  }
  const pct = Math.min(1, used / total);
  const near = pct >= 0.8;
  return (
    <span className="hint ctx-bar-inline" title={`${fmtTokens(used)} / ${fmtTokens(total)} tokens`}>
      <span className="ctx-bar-track" data-near={near ? "1" : undefined}>
        <span
          className="ctx-bar-fill"
          style={{ width: `${(pct * 100).toFixed(0)}%` }}
        />
      </span>
      {fmtTokens(used)}/{fmtTokens(total)}
    </span>
  );
}

function runtimeBadge(config: Config, endpoint: string): string {
  // Prefer the configured runtime for this endpoint.
  const ep = config.saved_endpoints.find((e) => e.url === endpoint);
  if (ep?.runtime) return RUNTIME_LABEL[ep.runtime] ?? ep.runtime.toUpperCase();
  // Fallback heuristics for ad-hoc endpoints not in the saved list.
  if (/openrouter\.ai/.test(endpoint)) return "OPENROUTER";
  return "OPENAI";
}

