/* ---------- context bar (inline, in composer row) ---------- */
.ctx-bar-inline {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  font-family: var(--mono);
  font-size: 11px;
  color: var(--dim);
  white-space: nowrap;
}
.ctx-bar-track {
  height: 3px;
  width: 32px;
  flex-shrink: 0;
  border-radius: 999px;
  background: var(--panel-3);
  overflow: hidden;
}
.ctx-bar-track[data-near="1"] .ctx-bar-fill {
  background: var(--warn);
}
.ctx-bar-fill {
  display: block;
  height: 100%;
  border-radius: 999px;
  background: var(--accent);
  transition: width 0.3s ease;
}

/* ---------- context tile bar (Status) ---------- */
.ctx-bar {
  position: relative;
  height: 4px;
  margin: 6px 0 2px;
  border-radius: 999px;
  background: var(--panel-3);
  overflow: hidden;
}
.ctx-bar::after {
  content: "";
  position: absolute;
  inset: 0;
  width: var(--ctx-pct, 0%);
  background: var(--accent);

