.composer {
  border-top: 1px solid var(--border-soft);
  padding: 14px 24px 18px;
}
.composer-inner {
  max-width: 820px;
  margin: 0 auto;
}
.composer-box {
  border: 1px solid var(--border);
  border-radius: 12px;
  background: var(--panel);
  padding: 10px 12px;
  transition: border-color 0.15s;
}
.composer-box:focus-within {
  border-color: var(--accent-dim);
}
.composer textarea {
  width: 100%;
  background: transparent;
  border: none;
  outline: none;
  resize: none;
  color: var(--text);
  font-family: var(--sans);
  font-size: 14.5px;
  line-height: 1.5;
  max-height: 220px;
}
.composer-row {
  display: flex;
  align-items: center;
  gap: 10px;
  margin-top: 8px;
}
.composer-row .hint {
  font-size: 11px;
  color: var(--dim);
}
.send-btn {
  margin-left: auto;
  background: var(--accent);
  color: #04201d;
  border: none;
  border-radius: 8px;
  padding: 7px 16px;
  font-weight: 600;
  font-size: 13px;
}
.send-btn:hover {
  background: #45cfc5;
}
.send-btn:disabled {
  background: var(--panel-3);
  color: var(--dim);
}
.stop-btn {
  margin-left: auto;
  background: transparent;
  color: var(--danger);
  border: 1px solid #5a2a2c;
  border-radius: 8px;
  padding: 7px 16px;
  font-size: 13px;
}

/* ---------- steering queue ---------- */
.queue-row {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
  margin-bottom: 8px;
}
.queue-chip {
  display: flex;
  align-items: center;
  gap: 6px;
  max-width: 100%;
  background: var(--panel-2);
  border: 1px dashed var(--border);
  border-radius: 8px;
  padding: 4px 6px 4px 10px;
  font-size: 12px;
  color: var(--muted);
}
.queue-chip-label {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  max-width: 320px;
}
.queue-chip-remove {
  background: transparent;
  border: none;
  color: var(--muted);
  cursor: pointer;
  font-size: 11px;
  line-height: 1;
  padding: 2px 4px;
}
.queue-chip-remove:hover {
  color: var(--danger);
}

/* ---------- compaction divider ---------- */
.compaction-divider {
  display: flex;
  align-items: center;
  justify-content: center;
  margin: 14px 0;
  color: var(--muted);
  font-size: 11.5px;
  letter-spacing: 0.02em;
}
.compaction-divider span {
  padding: 3px 12px;
  border: 1px dashed var(--border);
  border-radius: 999px;
  background: var(--panel);

